//
// Lane PLATFORMICON-1 (OpenBFME, not retail): the three platform icons (Windows / Linux / macOS) as mapped images, drawn left of a player's name
// (GameWindow::winSetBadge). The artwork is our own: plain monochrome glyphs (a window grid, a penguin, an apple) generated by
// tools/platformicon/make_icons.py into godot/assets/platform_icons/*.png (white on transparent, 32 x 32), never a vendor's logo.
// They are registered next to the retail mapped images under the names of PlatformKind (GameNetwork/PlatformKind.h platformImageName).

#pragma once

#include "GameClient/GUI/Image.h"
#include "GameNetwork/PlatformKind.h"

// the icons' resource folder in the Godot project and their size in pixels
constexpr const char *kPlatformIconDir = "res://assets/platform_icons/";
constexpr int kPlatformIconPixels = 32;
// the icon's size in stage pixels (the 1024 x 768 menu stage) when drawn
constexpr int kPlatformIconStage = 16;

inline const char *platformIconFile(PlatformKind k)
{
	switch (k)
	{
		case PlatformKind::Windows: return "res://assets/platform_icons/windows.png";
		case PlatformKind::Linux: return "res://assets/platform_icons/linux.png";
		case PlatformKind::MacOS: return "res://assets/platform_icons/macos.png";
		default: return "";
	}
}

// adds the three images (once: a name already in the collection is left as it is)
inline void registerPlatformIcons(MappedImageCollection &images)
{
	for (PlatformKind k : { PlatformKind::Windows, PlatformKind::Linux, PlatformKind::MacOS })
	{
		if (images.findImageByName(platformImageName(k)))
		{
			continue;
		}
		Image image;
		image.name = platformImageName(k);
		image.filename = platformIconFile(k);
		image.status = IMAGE_STATUS_ENGINE_RESOURCE;
		image.textureSize.x = image.textureSize.y = kPlatformIconPixels;
		image.imageSize.x = image.imageSize.y = kPlatformIconStage;
		image.uvLo[0] = image.uvLo[1] = 0.0f;
		image.uvHi[0] = image.uvHi[1] = 1.0f;
		images.addImage(image);
	}
}
